<?php
require_once __DIR__.'/config.php'; require_login();if(!fams_current_type_allows('AICS','view_reports')){http_response_code(403);exit('Your user type does not have permission for this action. Contact the Site Administrator if this access is required.');}
require_once __DIR__.'/fund_ledger.php';
$year=(int)($_GET['year']??date('Y')); $month=(int)($_GET['month']??date('n'));
if($year<2020 || $year>(int)date('Y') || $month<1 || $month>12){http_response_code(400);exit('Invalid reporting period.');}
$start=sprintf('%04d-%02d-01',$year,$month); $end=date('Y-m-d',strtotime($start.' +1 month'));
$st=$pdo->prepare("SELECT id,control_number,beneficiary_first_name,beneficiary_middle_name,beneficiary_last_name,municipality,guarantee_amount,status,date_submission,release_date FROM aics_assistance_records WHERE status='RELEASED' AND release_date>=? AND release_date<? ORDER BY release_date,id");
$st->execute([$start,$end]); $rows=$st->fetchAll();
$total=0.0; foreach($rows as $r)$total+=(float)$r['guarantee_amount'];
$fundMonthData=aics_fund_month($pdo,$year,$month);
$fundMonth=(float)$fundMonthData['additions'];
$openingBalance=(float)$fundMonthData['opening']; $remainingBalance=$openingBalance+$fundMonth-$total;
$monthName=date('F',strtotime($start));
$sheetRows=[];
foreach($rows as $r){
 $sheetRows[]=[
  'release_date'=>(string)($r['release_date']??''),
  'control_number'=>(string)($r['control_number']??''),
  'beneficiary'=>trim(($r['beneficiary_first_name']??'').' '.($r['beneficiary_middle_name']??'').' '.($r['beneficiary_last_name']??'')),
  'municipality'=>(string)($r['municipality']??''),
  'amount'=>(float)($r['guarantee_amount']??0),
 ];
}
$sheetJson=json_encode($sheetRows,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
?>
