ant-numeric:tabular-nums}.sheet-table .row-number{width:42px;text-align:center;color:#7890a3}.sheet-table .row-action{width:70px;text-align:center}.sheet-table .row-number{position:relative}.sheet-table .row-resizer{position:absolute;left:0;right:0;bottom:-3px;height:7px;cursor:row-resize;touch-action:none;z-index:8}.sheet-table .row-resizer:hover{background:#5ca9d2;opacity:.7}.sheet-table tfoot td{font-weight:850;background:#edf4f9;border-top:2px solid #b8cbd9}.sheet-note{padding:10px 12px;color:#60798d;font-size:10px}.sheet-footer{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;padding:28px 20px 24px;text-align:center}.sheet-footer .line{border-top:1px solid #52667d;padding-top:5px;font-weight:850}.editable-signature,.editable-designation{outline:none;display:inline-block;min-width:90px;padding:2px 4px}.editable-signature:focus,.editable-designation:focus{background:#fff8df;box-shadow:0 0 0 1px #c9a85c}.sheet-status{font-size:9px;font-weight:800;color:#53758e}.sheet-status.dirty{color:#a45c0a}.btn-danger{background:#fff!important;color:#a12e38!important;border-color:#e8c7cb!important}.sheet-toolbar button[aria-pressed="true"]{background:#175d8b!important;border-color:#175d8b!important;color:#fff!important}.sheet-table .col-resizer{position:absolute;right:-3px;top:0;width:8px;height:100%;cursor:col-resize;touch-action:none;z-index:10}.sheet-table .col-resizer:hover{background:#5ca9d2;opacity:.65}.empty-sheet{text-align:center;color:#6c8396;padding:30px!important}.no-print{display:block}
