<section class="report-summary balance-summary"><div class="summary-chip"><span>Beginning Balance</span><strong id="openingBalance">₱<?=number_format($openingBalance,2)?></strong></div><div class="summary-chip"><span>Less — Disbursed This Month</span><strong id="grandTotal">₱<?=number_format($total,2)?></strong></div><div class="summary-chip"><span>Downloaded This Month</span><strong id="downloadedBalance">₱<?=number_format($fundMonth,2)?></strong></div><div class="summary-chip"><span>Remaining Balance</span><strong id="remainingBalance">₱<?=number_format($remainingBalance,2)?></strong></div><div class="summary-chip"><span>Total Clients</span><strong id="recordCount"><?=number_format(count($sheetRows))?></strong></div><div class="summary-chip"><span>Worksheet Status</span><strong class="sheet-status" id="saveStatus">Ready</strong></div></section>
