<script>
(()=>{'use strict';const INITIAL=<?=$sheetJson?:'[]'?>;const YEAR=<?=$year?>,MONTH=<?=$month?>;const KEY='aics-period-sheet-v1:'+YEAR+'-'+String(MONTH).padStart(2,'0');const SIGNKEY='aics-period-signatories-v1';let rows=INITIAL.map(r=>({...r}));let editing=true;const body=document.getElementById('reportBody'),meta=document.getElementById('sheetMeta'),status=document.getElementById('saveStatus');const money=n=>'₱'+(Number(n)||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function persist(){try{localStorage.setItem(KEY,JSON.stringify(rows));status.textContent='Local edits saved';status.classList.add('dirty');}catch(e){status.textContent='Unsaved';}meta.textContent=`${<?=json_encode($monthName.' '.$year)?>} · ${rows.length} row(s) · Local worksheet`;updateTotals();}function render(){body.innerHTML='';rows.forEach((r,i)=>{const tr=document.createElement('tr');tr.innerHTML=`<td class="row-number">${i+1}<span class="row-resizer no-print" aria-hidden="true"></span></td><td class="editable" data-field="release_date">${esc(r.release_date)}</td><td class="editable" data-field="control_number">${esc(r.control_number)}</td><td class="editable" data-field="beneficiary">${esc(r.beneficiary)}</td><td class="editable" data-field="municipality">${esc(r.municipality)}</td><td class="editable amount" data-field="amount">${Number(r.amount||0).toFixed(2)}</td><td class="row-action no-print"><button class="btn btn-danger remove-row" type="button" aria-label="Remove row ${i+1}">×</button></td>`;tr.querySelectorAll('[data-field]').forEach(cell=>{cell.contentEditable=editing?'true':'false';cell.spellcheck=false;cell.addEventListener('input',()=>{const field=cell.dataset.field;rows[i][field]=field==='amount'?cell.textContent.replace(/[^0-9.\-]/g,''):cell.textContent.trim();persist();});cell.addEventListener('blur',()=>{if(cell.dataset.field==='amount'){const n=Number(rows[i].amount)||0;rows[i].amount=n;cell.textContent=n.toFixed(2);updateTotals();}});});tr.querySelector('.remove-row').addEventListener('click',()=>{rows.splice(i,1);render();persist();});body.appendChild(tr);});updateTotals();bindRowResize();}function updateTotals(){const total=rows.reduce((s,r)=>s+(Number(r.amount)||0),0);document.getElementById('recordCount').textContent=rows.length.toLocaleString('en-PH');document.getElementById('grandTotal').textContent=money(total);document.getElementById('footerTotal').textContent=money(total);document.getElementById('remainingBalance').textContent=money((<?=json_encode($openingBalance)?>)+(<?=json_encode($fundMonth)?>)-total);}document.getElementById('toggleEdit').addEventListener('click',e=>{editing=!editing;e.currentTarget.setAttribute('aria-pressed',editing?'true':'false');e.currentTarget.textContent=editing?'Editing Enabled':'Enable Editing';render();});document.getElementById('addRow').addEventListener('click',()=>{rows.push({release_date:'',control_number:'',beneficiary:'',municipality:'',amount:0});render();persist();body.lastElementChild?.querySelector('[data-field]')?.focus();});document.getElementById('resetEdits').addEventListener('click',()=>{if(!confirm('Discard local edits and restore the original database report?'))return;rows=INITIAL.map(r=>({...r}));try{localStorage.removeItem(KEY)}catch(e){}status.textContent='Reset to original';status.classList.remove('dirty');render();});function safeRows(){return rows.map(r=>({...r,amount:Number(r.amount)||0}));}document.getElementById('exportExcel').addEventListener('click',()=>{const data=safeRows();const html='<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial}table{border-collapse:collapse;width:100%}th{background:#123f67;color:white}th,td{border:1px solid #777;padding:5px}.amount{text-align:right}</style></head><body><h2>DSWD SWAD REGION II — AICS</h2><h3>'+esc(<?=json_encode(strtoupper($monthName.' '.$year).' ASSISTANCE RELEASE REPORT')?>)+'</h3><table><thead><tr><th>#</th><th>Release Date</th><th>Control No.</th><th>Beneficiary Name</th><th>Municipality</th><th>Amount (PHP)</th></tr></thead><tbody>'+data.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.release_date)}</td><td>${esc(r.control_number)}</td><td>${esc(r.beneficiary)}</td><td>${esc(r.municipality)}</td><td class="amount">${r.amount.toFixed(2)}</td></tr>`).join('')+'</tbody><tfoot><tr><th colspan="5">TOTAL</th><th>'+data.reduce((s,r)=>s+r.amount,0).toFixed(2)+'</th></tr></tfoot></table></body></html>';const blob=new Blob(['\ufeff',html],{type:'application/vnd.ms-excel;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='AICS_Selected_Period_'+YEAR+'-'+String(MONTH).padStart(2,'0')+'.xls';document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},1000);});const closeReport=()=>{try{window.close();}catch(e){}};document.getElementById('closeReport')?.addEventListener('click',closeReport);const signatureEls=[...document.querySelectorAll('.editable-signature,.editable-designation')];function saveSignatures(){const data={};signatureEls.forEach(el=>data[(el.dataset.signature?'name_':'designation_')+(el.dataset.signature||el.dataset.designation)]=el.textContent.trim());try{localStorage.setItem(SIGNKEY,JSON.stringify(data));}catch(e){}}try{const saved=JSON.parse(localStorage.getItem(SIGNKEY)||'{}');signatureEls.forEach(el=>{const key=(el.dataset.signature?'name_':'designation_')+(el.dataset.signature||el.dataset.designation);if(saved[key])el.textContent=saved[key];});}catch(e){}signatureEls.forEach(el=>el.addEventListener('input',saveSignatures));document.getElementById('saveSignDefaults')?.addEventListener('click',()=>{saveSignatures();status.textContent='Signatories saved as defaults';});const print=()=>window.print();document.getElementById('downloadPdf').addEventListener('click',print);document.getElementById('printReport').addEventListener('click',print);function bindResize(){document.querySelectorAll('#reportTable th .col-resizer').forEach(handle=>{handle.onpointerdown=e=>{e.preventDefault();handle.setPointerCapture?.(e.pointerId);const th=handle.parentElement,start=e.clientX,startWidth=th.getBoundingClientRect().width;const move=ev=>{const width=Math.max(65,startWidth+ev.clientX-start);th.style.width=width+'px';document.querySelectorAll('#reportTable tr').forEach(tr=>{if(tr.children[th.cellIndex])tr.children[th.cellIndex].style.width=width+'px';});};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up,{once:true});};});}function bindRowResize(){body.querySelectorAll('.row-resizer').forEach(handle=>{handle.onpointerdown=e=>{if(!editing)return;e.preventDefault();const tr=handle.closest('tr'),startY=e.clientY,startHeight=tr.getBoundingClientRect().height;const move=ev=>{tr.style.height=Math.max(24,Math.min(240,startHeight+ev.clientY-startY))+'px'};const stop=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',stop);};document.addEventListener('pointermove',move);document.addEventListener('pointerup',stop,{once:true});};});}try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(Array.isArray(parsed))rows=parsed;}}catch(e){}render();bindResize();bindRowResize();})();
</script></body></html>
